_FALLBACK_SRC = '# Exact action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Cost: cost_p = 3.0 * (trucks of p not on p\'s base)\n#              + 1.5 * (scooters of p not on p\'s base).\n# Service and costs use positions AFTER this turn\'s moves.\n#\n# Conservative operating envelope:\n# Each dispatched courier must be able to return home in ONE subsequent move.\n# Thus outbound service happens immediately and returning home costs nothing.\n# We never invest in speculative, unpaid outward travel. Against an idle\n# opponent, every dispatch has a strictly positive immediate profit.\n\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 60\nUNIT_TYPES = {\n    "truck": (8, 3.0, 1),\n    "scooter": (3, 1.5, 2),\n}\nMIN_NET_GAIN = 0.35\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        if 0 <= a < n and 0 <= b < n and a != b:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n    for neighbours in adjacency:\n        neighbours.sort()\n\n    distances = []\n    for source in range(n):\n        row = [n + 1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbour in adjacency[node]:\n                if row[neighbour] == n + 1:\n                    row[neighbour] = row[node] + 1\n                    queue.append(neighbour)\n        distances.append(row)\n    return distances\n\n\ndef payout(own_capacity, opponent_capacity, stock):\n    """The specification\'s capacity-share formula, including empty nodes."""\n    denominator = max(own_capacity + opponent_capacity, stock)\n    if denominator <= 0:\n        return 0.0\n    return own_capacity * stock / denominator\n\n\ndef homeward_destination(position, base, speed, distances):\n    """Minimum-distance legal return step; ties use the smallest node id."""\n    return min(\n        (node for node in range(len(distances))\n         if distances[position][node] <= speed),\n        key=lambda node: (distances[node][base], node),\n    )\n\n\ndef make_plan(obs, distances, deadline):\n    n = len(distances)\n    base = int(obs["player_base"])\n    enemy_base = int(obs["opponent_base"])\n    units = obs.get("player_units", {})\n    stocks = obs.get("stock", [])\n    turn = int(obs.get("turn", 0))\n\n    # Default: return home. Under this strategy\'s own invariant that is one\n    # free move. This also recovers sensibly from arbitrary supplied positions.\n    plan = {}\n    usable = []\n    for uid in sorted(units):\n        kind, position = units[uid]\n        if kind not in UNIT_TYPES or not 0 <= position < n:\n            continue\n        capacity, cost, speed = UNIT_TYPES[kind]\n        plan[uid] = homeward_destination(position, base, speed, distances)\n        usable.append((uid, position, capacity, cost, speed))\n\n    if turn >= N_TURNS or len(stocks) != n:\n        return plan\n\n    enemy_capacity = [0] * n\n    for kind, position in obs.get("opponent_units", {}).values():\n        if kind in UNIT_TYPES and 0 <= position < n:\n            enemy_capacity[position] += UNIT_TYPES[kind][0]\n\n    assigned_capacity = [0] * n\n    available = list(usable)\n\n    # At most twelve greedy assignments, not a search or rollout.\n    # A candidate must earn now, be reachable now, and have a free exit home.\n    # Exact marginal service prevents assigning surplus units to drained stock.\n    while available and time.perf_counter() < deadline:\n        best = None\n        best_key = None\n        for index, (uid, position, capacity, cost, speed) in enumerate(available):\n            for node in range(n):\n                if node == base or node == enemy_base:\n                    continue\n                if distances[position][node] > speed:\n                    continue\n                if distances[node][base] > speed:\n                    continue\n                # Deliberately avoid marginal contests rather than speculate\n                # about where the opponent will move this turn.\n                if enemy_capacity[node] > 0:\n                    continue\n\n                before = payout(\n                    assigned_capacity[node], enemy_capacity[node], stocks[node]\n                )\n                after = payout(\n                    assigned_capacity[node] + capacity,\n                    enemy_capacity[node],\n                    stocks[node],\n                )\n                net = after - before - cost\n                if net <= MIN_NET_GAIN:\n                    continue\n\n                # Largest sure profit first; equal opportunities prefer nearby\n                # destinations and deterministic node/unit ordering.\n                key = (\n                    -net,\n                    distances[position][node],\n                    distances[node][base],\n                    node,\n                    uid,\n                )\n                if best_key is None or key < best_key:\n                    best_key = key\n                    best = (index, uid, node, capacity)\n\n        if best is None:\n            break\n        index, uid, node, capacity = best\n        plan[uid] = node\n        assigned_capacity[node] += capacity\n        available.pop(index)\n\n    return plan\n\n\ndef legal_action(plan, obs, distances):\n    """Validate independently against START-of-turn positions."""\n    moves = {}\n    n = len(distances)\n    units = obs.get("player_units", {})\n    for uid in sorted(plan):\n        if not isinstance(uid, str) or uid not in units:\n            continue\n        kind, position = units[uid]\n        if kind not in UNIT_TYPES or not 0 <= position < n:\n            continue\n        destination = int(plan[uid])\n        if not 0 <= destination < n:\n            continue\n        if distances[position][destination] > UNIT_TYPES[kind][2]:\n            continue\n        if destination != position:\n            moves[uid] = int(destination)\n    return {"moves": moves}\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self._map_key = None\n        self._distances = None\n\n    def act(self, obs):\n        started = time.perf_counter()\n        deadline = started + max(0.0, 0.6 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return {"moves": {}}\n\n        # Only immutable map information is cached. Planning is entirely\n        # observation-driven and works on first calls or skipped turns.\n        edges = tuple((int(a), int(b)) for a, b in obs.get("edges", []))\n        key = (n, edges)\n        if key != self._map_key:\n            self._distances = preprocess_map(n, edges)\n            self._map_key = key\n\n        base = int(obs.get("player_base", -1))\n        if not 0 <= base < n:\n            return {"moves": {}}\n        plan = make_plan(obs, self._distances, deadline)\n        return legal_action(plan, obs, self._distances)\n'
